import {
  type Action,
  CoordinateTransformation,
  Scale,
  Vec2,
  vectorUtils,
} from 'ketcher-core';
import { throttle } from 'lodash';
import { getGroupIdsFromItemArrays } from './helper/getGroupIdsFromItems';
import RotateTool from './rotate';
import SelectTool from './select/select';
import { getDifference, rotatePoint } from './rotate-controller.utils';
import { normalizeAngle } from '../utils/normalizeAngle';
import FragmentSelectionTool from './fragmentSelection';
import type { SelectionRotationContext } from './select/selectionToolContext';

type RaphaelMouseHandler = (event: MouseEvent) => void;
type RaphaelDragHandler = (
  dxFromStart: number,
  dyFromStart: number,
  clientX: number,
  clientY: number,
  event: MouseEvent,
) => void;

interface RotationRaphaelElement {
  attr(attributes: Record<string, string | number>): this;
  clone(): RotationRaphaelElement;
  drag(
    onMove: RaphaelDragHandler,
    onStart?: RaphaelMouseHandler,
    onEnd?: RaphaelMouseHandler,
  ): this;
  getBBox(): { x: number; y: number; width: number; height: number };
  hover(onIn: RaphaelMouseHandler, onOut: RaphaelMouseHandler): this;
  mousedown(handler: RaphaelMouseHandler): this;
  mouseup(handler: RaphaelMouseHandler): this;
  remove(): void;
  rotate(angle: number, centerX: number, centerY: number): this;
  toBack(): this;
  transform(value: string): this;
  translate(x: number, y: number): this;
  undrag(): this;
  unhover(onIn: RaphaelMouseHandler, onOut: RaphaelMouseHandler): this;
  unmousedown(handler: RaphaelMouseHandler): this;
  unmouseup(handler: RaphaelMouseHandler): this;
}

interface RotationRaphaelSet extends RotationRaphaelElement {
  [index: number]: RotationRaphaelElement;
  push(...elements: RotationRaphaelElement[]): this;
}

type LinkState = 'long' | 'short' | 'moveCenter' | 'moveHandle';
type CrossState = 'active' | 'inactive' | 'offset' | 'move';
type HandleState = 'hoverIn' | 'hoverOut' | 'active' | 'move';
type SnapAngleIndicatorState = 'noLine' | 'noText' | 'default';

const STYLE = {
  HANDLE_MARGIN: 15,
  HANDLE_RADIUS: 10,
  INITIAL_COLOR: '#B4B9D6',
  ACTIVE_COLOR: '#365CFF',
};

const LEFT_ARROW_PATH =
  'M12.7034 14.8189L9.39616 17.6218L9.13674 16.1892C8.12927 16.0487 7.17132 15.6644 6.34605 15.0697C5.52078 14.475 4.85314 13.6878 4.40108 12.7766C3.94903 11.8653 3.72622 10.8575 3.75201 9.84062C3.7778 8.82373 4.0514 7.8285 4.54906 6.94133L5.8121 7.65148C5.45018 8.29719 5.24246 9.01784 5.20516 9.75712C5.16786 10.4964 5.302 11.2343 5.59709 11.9132C5.89218 12.592 6.34023 13.1935 6.90624 13.6705C7.47225 14.1475 8.1409 14.4872 8.85993 14.6631L8.62297 13.3587L12.7034 14.8189Z';
const RIGHT_ARROW_PATH =
  'M15.4493 13.0588L14.1862 12.3486C14.5482 11.7029 14.7559 10.9823 14.7932 10.243C14.8305 9.50371 14.6963 8.76582 14.4012 8.08695C14.1062 7.40809 13.6581 6.80665 13.0921 6.32962C12.5261 5.85259 11.8574 5.51288 11.1384 5.33704L11.3754 6.64501L7.29492 5.18124L10.6022 2.37834L10.8616 3.81095C11.8691 3.95145 12.827 4.33573 13.6523 4.93043C14.4776 5.52513 15.1452 6.31227 15.5973 7.22353C16.0493 8.13478 16.2721 9.1426 16.2463 10.1595C16.2205 11.1764 15.9469 12.1716 15.4493 13.0588Z';

class RotateController {
  isRotating!: boolean;
  private readonly editor: SelectionRotationContext;
  private readonly rotateTool: RotateTool;
  private originalCenter!: Vec2;
  private normalizedCenterInitialHandleVec!: Vec2;
  private handleCenter!: Vec2;
  private initialRadius!: number;
  private isMovingCenter!: boolean;

  private handle?: RotationRaphaelSet;
  private boundingRect?: RotationRaphaelElement;
  private cross?: RotationRaphaelSet;
  private link?: RotationRaphaelElement;
  private protractor?: RotationRaphaelSet;
  private rotateArc?: RotationRaphaelSet;
  private snapAngleIndicator?: RotationRaphaelSet;

  constructor(editor: SelectionRotationContext) {
    this.editor = editor;
    this.init();
    this.rotateTool = new RotateTool(this.editor, undefined);
  }

  private lastDelta: Vec2 | null = null;

  private init() {
    this.originalCenter = new Vec2();
    this.normalizedCenterInitialHandleVec = new Vec2();
    this.handleCenter = new Vec2();
    this.initialRadius = 0;
    this.isRotating = false;
    this.isMovingCenter = false;
    this.lastDelta = null;
  }

  private get render() {
    return this.editor.render;
  }

  private get paper() {
    return this.render.paper;
  }

  private get center() {
    return this.originalCenter
      .scaled(this.render.options.microModeScale)
      .add(this.render.options.offset);
  }

  rerender() {
    this.clean();
    this.init();
    this.show();
  }

  // Incremental sync during selection drag – translates existing
  // boundingRect/handle/cross/link by delta (model) without stale visel reads.
  reposition(delta: Vec2) {
    if (
      !this.handle ||
      !this.boundingRect ||
      this.isRotating ||
      this.isMovingCenter
    ) {
      return;
    }
    const explicit = this.editor.explicitSelected();
    const visibleAtoms =
      this.render.ctab.molecule.getSelectedVisibleAtoms(explicit);
    const { texts, rxnArrows, rxnPluses } = explicit;
    const isMoreThanOne =
      visibleAtoms.concat(texts || [], rxnArrows || [], rxnPluses || [])
        .length > 1;
    if (!isMoreThanOne) {
      return;
    }
    if (!delta) return;
    const scale = this.render.options.microModeScale;
    const zoom = this.render.options.zoom ?? 1;
    const totalCanvas = delta.scaled(scale).scaled(zoom);
    const lastTotalCanvas = this.lastDelta
      ? this.lastDelta.scaled(scale).scaled(zoom)
      : new Vec2(0, 0);
    const incCanvas = totalCanvas.sub(lastTotalCanvas);
    const incModel = delta.sub(this.lastDelta ?? new Vec2(0, 0));
    if (incCanvas.x === 0 && incCanvas.y === 0) {
      this.lastDelta = new Vec2(delta.x, delta.y);
      return;
    }
    this.lastDelta = new Vec2(delta.x, delta.y);
    this.originalCenter = this.originalCenter.add(incModel);
    this.handleCenter = this.handleCenter.add(incCanvas);
    this.boundingRect.translate(incCanvas.x, incCanvas.y);
    this.handle.translate(incCanvas.x, incCanvas.y);
    this.cross?.translate(incCanvas.x, incCanvas.y);
    this.link?.translate(incCanvas.x, incCanvas.y);
    this.updateFloatingToolsPosition();
  }

  clean() {
    this.editor.event.updateFloatingTools.dispatch({
      visible: false,
      rotateHandlePosition: new Vec2(),
    });

    this.handle?.unhover(this.hoverIn, this.hoverOut);
    this.handle?.unmousedown(this.dragStart);
    this.handle?.unmouseup(this.dragEnd);
    this.handle?.undrag();

    const crossArea = this.cross?.[1];
    crossArea?.unhover(this.hoverCrossIn, this.hoverCrossOut);
    crossArea?.unmousedown(this.dragCrossStart);
    crossArea?.unmouseup(this.dragCrossEnd);
    crossArea?.undrag();

    this.cross?.remove();
    delete this.cross;
    this.boundingRect?.remove();
    delete this.boundingRect;
    this.link?.remove();
    delete this.link;
    this.handle?.remove();
    delete this.handle;
    this.protractor?.remove();
    delete this.protractor;
    this.rotateArc?.remove();
    delete this.rotateArc;
    this.snapAngleIndicator?.remove();
    delete this.snapAngleIndicator;
    this.lastDelta = null;
  }

  /**
   * Revert rotation by pressing "Escape" key or "Right click" button
   */
  revert() {
    if (!this.rotateTool.dragCtx?.action || !this.isRotating) {
      return;
    }

    const action: Action = this.rotateTool.dragCtx.action;
    action.perform(this.render.ctab);
    this.render.update();
    this.rerender();
  }

  private isPartOfFragmentSelected() {
    const allAtoms = this.render.ctab.molecule.atoms;
    const selectedAtomIds = this.editor.selection()?.atoms ?? [];
    const selectedFragmentIdSet = new Set();

    selectedAtomIds.forEach((atomId) => {
      const fragmentId = allAtoms.get(atomId)?.fragment;
      selectedFragmentIdSet.add(fragmentId);
    });

    const nonSelectedAtoms = allAtoms.filter(
      (id) => !selectedAtomIds.includes(id),
    );
    return nonSelectedAtoms.some((atom) =>
      selectedFragmentIdSet.has(atom.fragment),
    );
  }

  private show() {
    const originalCenter = this.rotateTool.getCenter();
    const selection = this.editor.selection();
    const visibleAtoms =
      this.render.ctab.molecule.getSelectedVisibleAtoms(selection);

    const { texts, rxnArrows, rxnPluses } = selection || {};

    const isMoreThanOneItemBeingSelected =
      visibleAtoms.concat(texts || [], rxnArrows || [], rxnPluses || [])
        .length > 1;

    const currentTool = this.editor.tool();
    const enable =
      isMoreThanOneItemBeingSelected &&
      (currentTool instanceof SelectTool ||
        currentTool instanceof FragmentSelectionTool) &&
      originalCenter;

    if (!enable) {
      return;
    }

    this.originalCenter = originalCenter;
    this.lastDelta = new Vec2(0, 0);

    const rectStartY = this.drawBoundingRect(
      visibleAtoms,
      texts,
      rxnArrows,
      rxnPluses,
      selection?.bonds,
      selection?.rgroupAttachmentPoints,
    );

    this.handleCenter = new Vec2(
      this.center.x,
      rectStartY - STYLE.HANDLE_MARGIN - STYLE.HANDLE_RADIUS,
    );

    const handleCenterInViewport = CoordinateTransformation.canvasToView(
      this.handleCenter,
      this.render,
    );
    this.editor.event.updateFloatingTools.dispatch({
      visible: true,
      rotateHandlePosition: handleCenterInViewport,
    });

    this.drawLink();
    this.drawCross();
    this.drawHandle();

    this.handle?.hover(this.hoverIn, this.hoverOut);
    this.handle?.mousedown(this.dragStart);
    this.handle?.mouseup(this.dragEnd);
    this.handle?.drag(
      this.dragMove(),
      undefined,
      this.dragEnd, // Fix rotation getting stuck when mouseup outside window
    );

    if (this.isPartOfFragmentSelected()) {
      return;
    }

    const crossArea = this.cross?.[1];
    crossArea?.hover(this.hoverCrossIn, this.hoverCrossOut);
    crossArea?.mousedown(this.dragCrossStart);
    crossArea?.mouseup(this.dragCrossEnd);
    crossArea?.drag(
      this.dragCrossMove,
      undefined,
      this.dragCrossEndOUtOfBounding,
    );
  }

  private drawCross(state?: CrossState) {
    switch (state) {
      case 'active': {
        this.cross?.attr({
          stroke: STYLE.ACTIVE_COLOR,
        });
        break;
      }

      case 'inactive': {
        this.cross?.attr({
          stroke: STYLE.INITIAL_COLOR,
        });
        break;
      }

      case 'move': {
        this.cross?.transform('');
        this.cross?.translate(this.center.x, this.center.y);
        break;
      }

      default: {
        const cross = this.paper
          .path(`M0,0` + `h8` + `M0,0` + `h-8` + `M0,0` + `v8` + `M0,0` + `v-8`)
          .attr({
            stroke: STYLE.INITIAL_COLOR,
            'stroke-width': 2,
            'stroke-linecap': 'round',
          });
        // HACK: increase hover/drag area
        const circle = this.paper.circle(0, 0, 10).attr({
          fill: 'red',
          opacity: 0,
        });
        circle.node.setAttribute('data-testid', 'rotation-center-handle');
        this.cross = this.paper.set();
        this.cross?.push(cross, circle);
        this.cross?.translate(this.center.x, this.center.y);

        break;
      }
    }
  }

  private drawBoundingRect(
    visibleAtoms: number[],
    texts?: number[],
    rxnArrows?: number[],
    rxnPluses?: number[],
    bonds?: number[],
    rgroupAttachmentPoints?: number[],
  ) {
    const RECT_RADIUS = 20;
    const RECT_PADDING = 10;

    const rectBox = this.render.ctab
      .getVBoxObj({
        atoms: visibleAtoms,
        texts,
        rxnArrows,
        rxnPluses,

        sgroups: getGroupIdsFromItemArrays(this.render.ctab.molecule, {
          atoms: visibleAtoms,
        }),
        bonds,
        rgroupAttachmentPoints,
      })
      .transform(Scale.modelToCanvas, this.render.options)
      .translate(this.render.options.offset || new Vec2());

    const rectStartX =
      rectBox.p0.x -
      RECT_PADDING -
      this.render.options.atomSelectionPlateRadius;
    const rectStartY =
      rectBox.p0.y -
      RECT_PADDING -
      this.render.options.atomSelectionPlateRadius;
    const rectEndX =
      rectBox.p1.x +
      RECT_PADDING +
      this.render.options.atomSelectionPlateRadius;
    const rectEndY =
      rectBox.p1.y +
      RECT_PADDING +
      this.render.options.atomSelectionPlateRadius;

    this.boundingRect = this.paper
      .rect(
        rectStartX,
        rectStartY,
        rectEndX - rectStartX,
        rectEndY - rectStartY,
        RECT_RADIUS,
      )
      .attr({
        'stroke-dasharray': '-',
        stroke: STYLE.INITIAL_COLOR,
      });

    return rectStartY;
  }

  private drawHandle(state?: HandleState) {
    switch (state) {
      case 'hoverIn': {
        this.handle?.attr({
          cursor: 'grab',
        });
        const circle = this.handle?.[0];
        circle?.attr({
          fill: STYLE.ACTIVE_COLOR,
        });
        break;
      }

      case 'hoverOut': {
        const circle = this.handle?.[0];
        circle?.attr({
          fill: STYLE.INITIAL_COLOR,
        });
        break;
      }

      case 'active': {
        this.handle?.attr({
          cursor: 'grabbing',
        });
        const arrowSet = this.handle?.[1];
        arrowSet?.attr({ fill: 'none' });
        break;
      }

      case 'move': {
        this.handle
          ?.transform('')
          .translate(this.handleCenter.x, this.handleCenter.y);
        break;
      }

      default: {
        const circle = this.paper.circle(0, 0, STYLE.HANDLE_RADIUS).attr({
          fill: STYLE.INITIAL_COLOR,
          stroke: 'none',
        });
        circle.node.setAttribute('data-testid', 'rotation-handle');

        const leftArrow = this.paper
          .path(LEFT_ARROW_PATH)
          .attr({ fill: 'white', stroke: 'none' });
        const rightArrow = this.paper
          .path(RIGHT_ARROW_PATH)
          .attr({ fill: 'white', stroke: 'none' });
        const arrowSet: RotationRaphaelSet = this.paper.set();
        arrowSet.push(leftArrow, rightArrow);
        const { x, y, width, height } = arrowSet.getBBox();
        arrowSet.translate(-(x + width / 2), -(y + height / 2));

        const handle: RotationRaphaelSet = this.paper.set();
        handle.push(circle, arrowSet);
        handle.translate(this.handleCenter.x, this.handleCenter.y);
        this.handle = handle;
        break;
      }
    }
  }

  private drawLink(state?: LinkState) {
    switch (state) {
      case 'long': {
        this.link?.attr({
          path:
            `M${this.center.x},${this.center.y}` +
            `L${this.handleCenter.x},${this.handleCenter.y}`,
          stroke: STYLE.ACTIVE_COLOR,
        });
        break;
      }

      case 'short': {
        this.link?.attr({
          path:
            `M${this.handleCenter.x},${this.handleCenter.y}` +
            `l0,${STYLE.HANDLE_RADIUS + STYLE.HANDLE_MARGIN}`,
          stroke: STYLE.INITIAL_COLOR,
        });
        break;
      }

      case 'moveCenter':
      case 'moveHandle': {
        this.link?.attr({
          path:
            `M${this.center.x},${this.center.y}` +
            `L${this.handleCenter.x},${this.handleCenter.y}`,
        });
        break;
      }

      default: {
        this.link = this.paper
          .path(
            `M${this.handleCenter.x},${this.handleCenter.y}` +
              `l0,${STYLE.HANDLE_RADIUS + STYLE.HANDLE_MARGIN}`,
          )
          .attr({
            'stroke-dasharray': '-',
            stroke: STYLE.INITIAL_COLOR,
          });
        break;
      }
    }
  }

  private drawProtractor(
    structRotateDegree: number,
    radius: number,
    degreeLine: RotationRaphaelElement,
    textPos: Vec2,
  ) {
    this.protractor?.remove();

    const PROTRACTOR_COLOR = '#E1E5EA';
    const DEGREE_FONT_SIZE = 12;

    const circle = this.paper
      .circle(this.center.x, this.center.y, radius)
      .attr({
        'stroke-dasharray': '-',
        stroke: PROTRACTOR_COLOR,
      });

    const protractor: RotationRaphaelSet = this.paper.set();
    protractor.push(circle);
    this.protractor = protractor;

    const predefinedDegrees = [
      0, 30, 45, 60, 90, 120, 135, 150, 180, -150, -135, -120, -90, -60, -45,
      -30,
    ];
    let previousDegree = 0;
    predefinedDegrees.forEach((currentDegree, currentIndex) => {
      const isDrawingDegree0 = currentIndex === 0;
      const gap = currentDegree - previousDegree;
      const diff = getDifference(currentDegree, structRotateDegree);

      if (!isDrawingDegree0) {
        degreeLine = degreeLine
          .clone()
          .rotate(gap, this.center.x, this.center.y);
      }

      degreeLine.attr({
        stroke: diff > 90 ? 'none' : PROTRACTOR_COLOR,
      });
      this.protractor?.push(degreeLine);

      if (radius < 65) {
        previousDegree = currentDegree;
        return;
      }

      textPos = rotatePoint(this.center, textPos, (gap / 180) * Math.PI);
      let degreeTextFill = STYLE.INITIAL_COLOR;

      if (diff > 90) {
        degreeTextFill = 'none';
      } else if (currentDegree !== 0 && currentDegree === structRotateDegree) {
        degreeTextFill = STYLE.ACTIVE_COLOR;
      }

      const degreeText = this.paper
        .text(textPos.x, textPos.y, `${currentDegree}°`)
        .attr({
          fill: degreeTextFill,
          'font-size': DEGREE_FONT_SIZE,
        });

      this.protractor?.push(degreeText);
      previousDegree = currentDegree;
    });

    protractor.toBack();
  }

  private drawRotateArc(
    structRotateDegree: number,
    radius: number,
    rotateArcStart: Vec2,
    textPos: Vec2,
  ) {
    let rotateArc: RotationRaphaelSet;
    if (this.rotateArc) {
      rotateArc = this.rotateArc;
    } else {
      const arc = this.paper.path();
      const text = this.paper.text(0, 0, '');

      rotateArc = this.paper.set().push(arc, text);
      this.rotateArc = rotateArc;
    }

    const rotateArcEnd = rotatePoint(
      this.center,
      rotateArcStart,
      (structRotateDegree / 180) * Math.PI,
    );

    const arc = rotateArc[0];
    const text = rotateArc[1];

    const TEXT_FONT_SIZE = 16;
    const TEXT_COLOR = '#333333';

    // Doc: https://www.w3.org/TR/SVG/paths.html#PathDataEllipticalArcCommands
    arc
      .attr({
        path:
          `M${rotateArcStart.x},${rotateArcStart.y}` +
          `A${radius},${radius} ` +
          `0 0,${structRotateDegree < 0 ? '0' : '1'} ` +
          `${rotateArcEnd.x},${rotateArcEnd.y}`,
        stroke: STYLE.ACTIVE_COLOR,
      })
      .toBack();

    text.attr({
      text: `${structRotateDegree}°`,
      x: textPos.x,
      y: textPos.y,
      'font-size': TEXT_FONT_SIZE,
      fill: TEXT_COLOR,
    });
  }

  // NOTE: When handle is non-arrow function, `this` is element itself
  private readonly hoverIn = (event: MouseEvent) => {
    const isSomeButtonPressed = event.buttons !== 0;
    if (isSomeButtonPressed) {
      return;
    }

    this.drawHandle('hoverIn');
  };

  private readonly hoverOut = (event: MouseEvent) => {
    const isSomeButtonPressed = event.buttons !== 0;
    if (isSomeButtonPressed) {
      return;
    }

    this.drawHandle('hoverOut');
  };

  private getProtractorBaseInfo(radius: number) {
    const DEGREE_TEXT_MARGIN = 10;

    const distBetweenDegree0TextAndCenter =
      radius +
      STYLE.HANDLE_MARGIN +
      STYLE.HANDLE_RADIUS * 2 +
      DEGREE_TEXT_MARGIN;
    const centerDegree0TextVec = this.normalizedCenterInitialHandleVec.scaled(
      distBetweenDegree0TextAndCenter,
    );
    const degree0TextPos = this.center.add(centerDegree0TextVec);

    const lineLength =
      radius >= 65 ? STYLE.HANDLE_MARGIN : STYLE.HANDLE_MARGIN / 2;
    const centerLineStartVec =
      this.normalizedCenterInitialHandleVec.scaled(radius);
    const lineVec = this.normalizedCenterInitialHandleVec.scaled(lineLength);
    const lineStart = this.center.add(centerLineStartVec);
    const lineEnd = lineStart.add(lineVec);
    const lineEndHalf = lineStart.addScaled(lineVec, 1 / 2);
    const degree0Line = this.paper
      .path(
        `M${lineStart.x},${lineStart.y}` +
          (radius >= 65
            ? `L${lineEnd.x}, ${lineEnd.y}`
            : `L${lineEndHalf.x}, ${lineEndHalf.y}`),
      )
      .attr({
        'stroke-dasharray': '-',
      });

    const arcStartPos = this.center.add(
      this.normalizedCenterInitialHandleVec.scaled(radius),
    );

    const TEXT_MARGIN_LEFT = 20;
    const l1 = centerLineStartVec.add(lineVec);
    const l2 = l1
      .rotate(Math.PI / 2)
      .normalized()
      .scaled(TEXT_MARGIN_LEFT);
    const currentDegreeMarkPos = this.center.add(l1).add(l2);

    return [
      degree0Line,
      degree0TextPos,
      arcStartPos,
      currentDegreeMarkPos,
    ] as const;
  }

  private readonly dragStart = (event: MouseEvent) => {
    event.stopPropagation(); // Avoid triggering SelectTool's mousedown

    const isLeftButtonPressed = event.buttons === 1;
    if (!isLeftButtonPressed) {
      return;
    }

    const isDragPaused = this.isRotating;
    if (isDragPaused) {
      // Fix protractor staying after screenshot/being paused
      // see https://github.com/epam/ketcher/pull/2574#issuecomment-1539201020
      this.clean();
      return;
    }

    this.isRotating = true;

    this.editor.event.updateFloatingTools.dispatch({
      visible: false,
      rotateHandlePosition: new Vec2(),
    });

    this.boundingRect?.remove();
    delete this.boundingRect;

    const centerHandleVec = this.handleCenter.sub(this.center);
    this.normalizedCenterInitialHandleVec = centerHandleVec.normalized();

    const newProtractorRadius =
      Vec2.dist(this.handleCenter, this.center) -
      STYLE.HANDLE_MARGIN -
      STYLE.HANDLE_RADIUS;
    this.initialRadius = newProtractorRadius >= 0 ? newProtractorRadius : 0;
    const [degree0Line, degree0TextPos] = this.getProtractorBaseInfo(
      this.initialRadius,
    );
    this.drawProtractor(0, this.initialRadius, degree0Line, degree0TextPos);

    this.drawCross('active');
    this.drawLink('long');
    this.drawHandle('active');

    const originalHandleCenter = this.handleCenter
      .sub(this.render.options.offset)
      .scaled(1 / this.render.options.microModeScale);
    this.rotateTool.mousedownHandle(originalHandleCenter, this.originalCenter);
  };

  private readonly dragMove = () => {
    let lastSnappingRadius: number | undefined;
    return throttle(
      (
        _dxFromStart: number,
        _dyFromStart: number,
        _clientX: number,
        _clientY: number,
        event: MouseEvent,
      ) => {
        if (!this.isRotating) {
          return;
        }

        this.handleCenter = CoordinateTransformation.pageToModel(
          event,
          this.render,
        )
          .scaled(this.render.options.microModeScale)
          .add(this.render.options.offset);

        this.drawLink('moveHandle');
        this.drawHandle('move');
        this.drawCross('move');

        this.rotateTool.mousemove(event);

        const newProtractorRadius =
          Vec2.dist(this.handleCenter, this.center) -
          STYLE.HANDLE_MARGIN -
          STYLE.HANDLE_RADIUS;
        let newRadius = newProtractorRadius >= 0 ? newProtractorRadius : 0;
        lastSnappingRadius = lastSnappingRadius ?? this.initialRadius;
        if (
          newRadius >= lastSnappingRadius * 1.4 ||
          newRadius <= lastSnappingRadius / 1.4
        ) {
          lastSnappingRadius = newRadius;
        } else {
          newRadius = lastSnappingRadius;
        }

        const [degree0Line, degree0TextPos, rotateArcStart, textPos] =
          this.getProtractorBaseInfo(newRadius);
        this.drawRotateArc(
          this.rotateTool.dragCtx?.angle ?? 0,
          newRadius,
          rotateArcStart,
          textPos,
        );
        // NOTE: draw protractor behind arc
        this.drawProtractor(
          this.rotateTool.dragCtx?.angle ?? 0,
          newRadius,
          degree0Line,
          degree0TextPos,
        );

        this.updateSnapAngleIndicator();
      },
      40, // 25fps
    );
  };

  private readonly dragEnd = (event: MouseEvent) => {
    event.stopPropagation(); // Avoid triggering SelectTool's mouseup

    this.rotateTool.mouseup();
    this.rerender();
  };

  private readonly hoverCrossIn = (event: MouseEvent) => {
    const isSomeButtonPressed = event.buttons !== 0;
    if (isSomeButtonPressed) {
      return;
    }

    this.drawCross('active');
    this.drawLink('long');
  };

  private readonly hoverCrossOut = (event: MouseEvent) => {
    const isSomeButtonPressed = event.buttons !== 0;
    if (isSomeButtonPressed) {
      return;
    }

    this.drawCross('inactive');
    this.drawLink('short');
  };

  private readonly dragCrossStart = (event: MouseEvent) => {
    event.stopPropagation();
    this.isMovingCenter = true;
  };

  private readonly dragCrossMove = throttle(
    (
      _dxFromStart: number,
      _dyFromStart: number,
      _clientX: number,
      _clientY: number,
      event: MouseEvent,
    ) => {
      if (!this.isMovingCenter) {
        return;
      }

      this.originalCenter = CoordinateTransformation.pageToModel(
        event,
        this.render,
      );

      this.drawCross('move');
      this.drawLink('moveCenter');
    },
    40,
  );

  private readonly dragCrossEnd = (event: MouseEvent) => {
    event.stopPropagation();

    this.isMovingCenter = false;
    this.originalCenter = CoordinateTransformation.pageToModel(
      event,
      this.render,
    );
  };

  private readonly dragCrossEndOUtOfBounding = (_event: MouseEvent) => {
    this.isMovingCenter = false;
    this.rerender();
  };

  updateFloatingToolsPosition = () => {
    if (!this.handle) {
      return;
    }

    const handleCenterInViewport = CoordinateTransformation.canvasToView(
      this.handleCenter,
      this.render,
    );
    this.editor.event.updateFloatingTools.dispatch({
      rotateHandlePosition: handleCenterInViewport,
    });
  };

  private updateSnapAngleIndicator() {
    const snapAngleDrawingProps = this.rotateTool.snapAngleDrawingProps;
    if (
      snapAngleDrawingProps === null ||
      (snapAngleDrawingProps.snapMode === 'multiple-bonds' &&
        snapAngleDrawingProps.isSnapping)
    ) {
      this.snapAngleIndicator?.remove();
    } else {
      const { isSnapping, absoluteAngle, relativeAngle, snapMode } =
        snapAngleDrawingProps;
      let drawingState: SnapAngleIndicatorState = 'default';

      if (isSnapping) {
        drawingState = 'noLine';
      } else if (snapMode === 'multiple-bonds') {
        drawingState = 'noText';
      }
      this.drawSnapAngleIndicator(drawingState, absoluteAngle, relativeAngle);
    }
  }

  private drawSnapAngleIndicator(
    state: SnapAngleIndicatorState,
    absoluteSnapAngle: number,
    relativeSnapAngle: number,
  ) {
    this.snapAngleIndicator?.remove();
    const snapAngleIndicator: RotationRaphaelSet = this.paper.set();
    this.snapAngleIndicator = snapAngleIndicator;
    const LINE_LENGTH = 30;
    const TEXT_FONT_SIZE = 12;
    const relativeSnapAngleInDegrees = vectorUtils.degrees(relativeSnapAngle);

    const drawText = (textPosition: Vec2) =>
      this.paper
        .text(
          textPosition.x,
          textPosition.y,
          `${Math.abs(relativeSnapAngleInDegrees)}°`,
        )
        .attr({
          'font-size': TEXT_FONT_SIZE,
        });

    const drawLine = () => {
      const lineVector = new Vec2(LINE_LENGTH, 0).rotate(absoluteSnapAngle);
      return this.paper.path(`M0,0` + `l${lineVector.x},${lineVector.y}`).attr({
        'stroke-dasharray': '-',
        stroke: STYLE.INITIAL_COLOR,
      });
    };

    switch (state) {
      case 'noLine': {
        const textAngle = normalizeAngle(
          absoluteSnapAngle - relativeSnapAngle / 2,
        );
        const textPosition = new Vec2(20, 0).rotate(textAngle);
        const text = drawText(textPosition).attr({
          fill: STYLE.ACTIVE_COLOR,
        });
        snapAngleIndicator.push(text);
        break;
      }

      case 'noText': {
        const line = drawLine();
        snapAngleIndicator.push(line);
        break;
      }

      default: {
        const line = drawLine();
        const textPosition = new Vec2(LINE_LENGTH + 15, 0).rotate(
          absoluteSnapAngle,
        );
        const text = drawText(textPosition).attr({
          fill: STYLE.INITIAL_COLOR,
        });
        snapAngleIndicator.push(line);
        snapAngleIndicator.push(text);
        break;
      }
    }

    snapAngleIndicator.translate(this.center.x, this.center.y);
  }
}

export default RotateController;
export { getDifference };
