import MuiSelect, { type SelectChangeEvent } from '@mui/material/Select';
import Divider from '@mui/material/Divider';
import MenuItem from '@mui/material/MenuItem';
import type { ReactNode } from 'react';
import clsx from 'clsx';
import styles from './Select.module.less';
import { Icon } from 'components';

export interface Option {
  value: string;
  label: string;
  children?: ReactNode;
  disabled?: boolean;
  markedAsUsed?: boolean;
}

interface Props {
  options: Array<Option>;
  onChange: (value: string) => void;
  className?: string;
  value?: string | number;
  multiple?: boolean;
  disabled?: boolean;
  formName?: string;
  name?: string;
  placeholder?: string;
  'data-testid'?: string;
  error?: boolean;
  title?: string;
}

const ChevronIcon = ({ className }) => (
  <Icon name="chevron" className={className} />
);

const Select = ({
  className,
  value,
  onChange,
  multiple = false,
  disabled,
  options,
  formName,
  name,
  placeholder,
  'data-testid': testId,
  error,
  title,
}: Props) => {
  const currentValue = options?.find((option) => option.value === value);
  const isFullscreen = !!document.fullscreenElement;
  const portalContainer = isFullscreen
    ? document.querySelector('#root')
    : undefined;

  const handleChange = (event: SelectChangeEvent) => {
    onChange(event.target.value);
  };

  return (
    <MuiSelect
      className={clsx(styles.selectContainer, className)}
      value={currentValue?.value ?? ''}
      title={title}
      onChange={handleChange}
      renderValue={(selected: string) =>
        currentValue?.children ?? currentValue?.label ?? placeholder ?? selected
      }
      displayEmpty
      multiple={multiple}
      disabled={disabled}
      placeholder={placeholder}
      MenuProps={{
        container: portalContainer,
        className: styles.dropdownList,
      }}
      IconComponent={ChevronIcon}
      data-testid={testId}
      error={error}
    >
      {options?.map((option) => {
        const isDivider: boolean =
          typeof option?.value === 'string'
            ? option.value.includes('Divider')
            : false;

        return isDivider ? (
          <Divider className={styles.listDivider} key={option.value} />
        ) : (
          <MenuItem
            value={option.value}
            key={option.value}
            disableRipple={true}
            disabled={option.disabled}
            title={option.markedAsUsed ? 'Already in use' : undefined}
            className={clsx({
              [`dropdown-${formName}_${name}`]: formName,
              [styles.usedOption]: option.markedAsUsed,
            })}
            data-testid={`${option.label}-option`}
          >
            <>{option.children ?? option.label}</>
          </MenuItem>
        );
      })}
    </MuiSelect>
  );
};

export default Select;
