class Attach extends Component<AttachProps> {
  mode: 'save' | 'edit';
  tmpl: NormalizedTemplate;
  oldKetcherEditor: Editor;

  constructor(props: AttachProps) {
    super(props);
    const { onInit, ...rest } = props;
    this.mode = isEmpty(rest.tmpl.props) ? 'save' : 'edit';
    this.tmpl = initTmpl(rest.tmpl);
    onInit(this.tmpl.struct.name, this.tmpl.props);
    this.onResult = this.onResult.bind(this);
    const ketcher = ketcherProvider.getKetcher(rest.ketcherId);
    this.oldKetcherEditor = ketcher.editor;
  }

  componentWillUnmount() {
    const ketcher = ketcherProvider.getKetcher(this.props.ketcherId);
    ketcher.addEditor(this.oldKetcherEditor);
  }

  onResult() {
    const { name, atomid, bondid } = this.props;
    return name &&
      (name !== this.tmpl.struct.name ||
        atomid !== this.tmpl.props.atomid ||
        bondid !== this.tmpl.props.bondid) &&
      name.trim().length
      ? { name, attach: { atomid, bondid } }
      : null;
  }

  checkIsValidName(name: string) {
    const trimmedName = name?.trim() ?? '';
    return (
      trimmedName.length > 0 &&
      !this.props.templateLib.some(
        (tmpl) =>
          !(this.mode === 'edit' && tmpl === this.props.tmpl) &&
          tmpl.struct.name.trim() === trimmedName &&
          tmpl.props.group === 'User Templates',
      ) &&
      name.length <= 128
    );
  }

  render() {
    const { name, onNameEdit, onAttachEdit, ...prop } = this.props;
    const struct = this.tmpl.struct;
    const { atomid, bondid } =
      struct.atoms.get(this.props.atomid) && struct.bonds.get(this.props.bondid)
        ? this.props
        : this.tmpl.props;
    const options = Object.assign(editorStyles, this.props.globalSettings, {
      microModeScale: getScale(struct),
      reuseRestructIfExist: false,
    });
    const dialogTitle =
      this.mode === 'save' ? 'Save to Templates' : 'Template Edit';
    const warningObject =
      this.mode === 'save' ? 'Templates' : 'Edited templates';

    return (
      <TemplateEditDialog
        title={dialogTitle}
        result={this.onResult}
        valid={() => this.props.formState.valid && this.checkIsValidName(name)}
        params={prop}
        buttons={[]}
        needMargin={false}
      >
        <Message>
          <div>
            {warningObject} are saved locally and cannot be accessed on
            different browsers or computers.
          </div>
          <div>
            Be aware that other users of the same computer and browser can
            access them as well.
          </div>
        </Message>
        <Form
          schema={attachSchema}
          customValid={{
            name: (name) => this.checkIsValidName(name),
          }}
          {...this.props.formState}
        >
          <LeftColumn>
            <EditorContainer>
              <StructEditor
                className="structEditor"
                ketcherId={this.props.ketcherId}
                struct={struct}
                onAttachEdit={onAttachEdit}
                tool="attach"
                toolOpts={{ atomid, bondid }}
                options={options}
                showAttachmentPoints={false}
              />
            </EditorContainer>
            {!storage.isAvailable() ? (
              <Warning>{storage.warningMessage}</Warning>
            ) : null}
          </LeftColumn>
          <RightColumn>
            <NameInput
              name="name"
              value={name}
              onChange={(value) => onNameEdit(value as string)}
              placeholder="template"
            />
            <span>Selected attachment points</span>
            <AttachmentOutput data-testid="attach-output">
              Atom ID: <strong>{atomid}</strong> Bond ID:{' '}
              <strong>{bondid}</strong>
            </AttachmentOutput>
            <Buttons>
              <CancelButton
                variant="outlined"
                onClick={this.props.onCancel}
                className={classes.button}
                data-testid="template-cancel-button"
              >
                Cancel
              </CancelButton>
              <SaveButton
                variant="contained"
                onClick={() => this.props.onOk(this.onResult())}
                className={classes.button}
                disabled={!this.checkIsValidName(name)}
                data-testid={
                  this.mode === 'save'
                    ? 'template-save-button'
                    : 'template-edit-button'
                }
              >
                {this.mode === 'save' ? 'Save' : 'Edit'}
              </SaveButton>
            </Buttons>
          </RightColumn>
        </Form>
      </TemplateEditDialog>
    );
  }
}

const mapStateToProps = (store: StoreState): AttachStateProps => ({
  ...store.templates.attach,
  templateLib: store.templates.lib,
  formState: store.modal.form,
  globalSettings: store.options.settings,
});

const mapDispatchToProps = (dispatch: Dispatch): AttachDispatchProps => ({
  onInit: (name: string, ap: AttachPoints) => dispatch(initAttach(name, ap)),
  onAttachEdit: (ap: AttachPoints) => dispatch(setAttachPoints(ap)),
  onNameEdit: (name: string) => dispatch(setTmplName(name)),
});

const connector = connect(mapStateToProps, mapDispatchToProps);
export default connector(Attach);

function initTmpl(tmpl: TemplateItem): NormalizedTemplate {
  const normTmpl = {
    struct: structNormalization(tmpl.struct),
    props: {
      atomid: Number(tmpl.props.atomid) || 0,
      bondid: Number(tmpl.props.bondid) || 0,
    },
  };
  normTmpl.struct.name = tmpl.struct.name;
  return normTmpl;
}

function structNormalization(struct: Struct): Struct {
  const normStruct = struct.clone();
  const cbb = normStruct.getCoordBoundingBox();

  normStruct.atoms.forEach((atom) => {
    atom.pp = atom.pp.sub(cbb.min);
  });

  normStruct.sgroups.forEach((sg) => {
    sg.pp = sg.pp ? sg.pp.sub(cbb.min) : cbb.min;
  });

  normStruct.rxnArrows.forEach((rxnArrow) => {
    rxnArrow.pos = rxnArrow.pos.map((p) => p.sub(cbb.min));
  });

  normStruct.rxnPluses.forEach((rxnPlus) => {
    rxnPlus.pp = rxnPlus.pp.sub(cbb.min);
  });

  normStruct.simpleObjects.forEach((simpleObject) => {
    simpleObject.pos = simpleObject.pos.map((p) => p.sub(cbb.min));
  });

  normStruct.texts.forEach((text) => {
    text.position = text.position.sub(cbb.min);
  });

  return normStruct;
}

function getScale(struct: Struct): number {
  const cbb = struct.getCoordBoundingBox();
  const VIEW_SIZE = 220;
  const scale =
    VIEW_SIZE / Math.max(cbb.max.y - cbb.min.y, cbb.max.x - cbb.min.x);
  if (scale < 35) return 35;
  if (scale > 50) return 50;
  return 40;
}
